#!/usr/bin/env bun
/**
 * Database management script
 *
 * Usage:
 *   bun run db start      # Start PostgreSQL container
 *   bun run db stop       # Stop PostgreSQL container
 *   bun run db migrate    # Run Prisma migrations
 *   bun run db push       # Push schema to database
 *   bun run db seed       # Seed the database
 *   bun run db generate   # Generate Prisma client
 *   bun run db studio     # Open Prisma Studio
 *   bun run db reset      # Reset database (destructive)
 */

import { $ } from "bun";
import { existsSync } from "fs";
import { resolve } from "path";

const command = process.argv[2];

const runCommand = async (label: string, cmd: string[]) => {
  console.log(`\n📋 ${label}...`);
  try {
    await $`${cmd}`;
    console.log(`✅ ${label} complete`);
  } catch (error) {
    console.error(`❌ ${label} failed`);
    process.exit(1);
  }
};

const projectRoot = resolve(import.meta.dir, "..");
const dockerComposePath = resolve(projectRoot, "docker/docker-compose.dev.yml");

const commands: Record<string, () => Promise<void>> = {
  start: async () => {
    console.log("🚀 Starting PostgreSQL...");
    // Check if already running
    try {
      await $`docker compose -f ${dockerComposePath} ps --status running db`;
      console.log("✅ PostgreSQL is already running");
      return;
    } catch {
      // Not running, start it
      await runCommand(
        "Starting PostgreSQL container",
        ["docker", "compose", "-f", dockerComposePath, "up", "-d", "--wait"]
      );
    }
  },

  stop: async () => {
    await runCommand(
      "Stopping PostgreSQL",
      ["docker", "compose", "-f", dockerComposePath, "down"]
    );
  },

  migrate: async () => {
    await runCommand(
      "Running migrations",
      ["bunx", "prisma", "migrate", "dev"]
    );
  },

  push: async () => {
    await runCommand(
      "Pushing schema to database",
      ["bunx", "prisma", "db", "push"]
    );
  },

  seed: async () => {
    await runCommand("Seeding database", ["bun", "run", "prisma/seed.ts"]);
  },

  generate: async () => {
    await runCommand("Generating Prisma client", ["bunx", "prisma", "generate"]);
  },

  studio: async () => {
    console.log("🎨 Opening Prisma Studio...");
    await $`bunx prisma studio`;
